        for i in range(n):
            for j in range(m):
                if f[i + j * m]:
                    S[2 * i][2 * j] = 1
                    S[2 * i + 1][2 * j + 1] = 1
                    S[2 * i][2 * j + 1] = -1
                    S[2 * i + 1][2 * j] = -1

        return S

    def communication_complexity(f):
        n = int(math.log2(len(f)))
        m = n
        cc = 0

        for i in range(n):
            for j in range(m):
                if f[i + j * m]:
                    cc += 1

        return cc

    def gaussian_elimination(matrix):
        rows, cols = len(matrix), len(matrix[0])
        rank = 0
        pivot_col = 0

        for i in range(rows):
            while pivot_col < cols and all(matrix[i][j] == 0 for j in range(pivot_col, cols)):
                pivot_col += 1

            if pivot_col >= cols:
                break

            matrix[i], matrix[pivot_row] = matrix[pivot_row], matrix[i]

            for j in range(rows):
                if i != j and matrix[j][pivot_col] != 0:
                    factor = -matrix[j][pivot_col] / matrix[i][pivot_col]
                    for k in range(cols):
                        matrix[j][k] += factor * matrix[i][k]

            pivot_row += 1
            rank += 1

        return rank

    n_values = [5, 10, 15, 20, 30, 40]
    min_ranks = []
    comm_complexities = []

    for n in n_values:
        f = generate_boolean_function(n)
        S = construct_symplectic_matrix(f)
        cc = communication_complexity(f)

